package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.lianxibu.site.controller.jobs.JobsController;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.identity.IdentityService;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import tools.jackson.databind.json.JsonMapper;

/** Original native external result provider/core; authentication alone is a fictional port. */
@EnabledIfEnvironmentVariable(named="B44_MYSQL",matches="true")
class OwnerExternalResolutionHttpMySqlTest {
    OwnerExternalResolutionMaterialMySqlTest t;MockMvc mvc;IdentityService auth;
    @BeforeEach @SuppressWarnings("unchecked") void setup(){t=new OwnerExternalResolutionMaterialMySqlTest();t.setup();auth=mock(IdentityService.class);when(auth.authenticate("fictional-session")).thenReturn(t.OWNER);when(auth.authorizeWrite("fictional-session","fictional-csrf","https://site.example.invalid")).thenReturn(t.OWNER);ObjectProvider<IdentityService> identity=mock(ObjectProvider.class);when(identity.getIfAvailable()).thenReturn(auth);ObjectProvider<JobsService> jobs=mock(ObjectProvider.class);var cancel=new OwnerJobCancelService(t.f.writes,new JdbcOwnerJobCancellation(t.f.source),t.f.clock);var resolution=new OwnerJobResolveExternalService(t.f.source,t.f.tx,t.f.writes,t.f.clock);when(jobs.getIfAvailable()).thenReturn(new OwnerJobsService(mock(OwnerJobsReadService.class),new OwnerJobCommandsService(cancel,null,null,null,null,resolution)));mvc=MockMvcBuilders.standaloneSetup(new JobsController(identity,jobs)).build();}
    String command(String state){var c=t.command(state);var n=JsonMapper.shared().createObjectNode().put("expected_revision",c.expectedRevision()).put("action",c.action()).put("reason",c.reason()).put("attempt_id",c.attemptId()).put("external_state",state);n.set("evidence_refs",JsonMapper.shared().valueToTree(c.evidenceRefs()));if(c.result()==null)n.putNull("result");else {var r=n.putObject("result").put("schema_version",c.result().schemaVersion()).put("input_hash",c.result().inputHash()).put("result_hash",c.result().resultHash());r.set("payload",c.result().payload());}n.putNull("usage");return JdbcFrozenInputs.canonical(n);}
    org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder action(String body,String key){return post("/admin/jobs/"+ResultJdbcStoreTest.ROOT+"/actions").cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session")).header("X-CSRF-Token","fictional-csrf").header("Origin","https://site.example.invalid").header("Idempotency-Key",key).contentType("application/json").content(body);}
    @Test void ActualHttpSuccessRetainsFullOriginalResultAndReplaysWithoutApplyingContent() throws Exception {String body=command("succeeded");long before=t.read().root().revision();var slot=new JdbcWorkerState(t.f.source).slot();var first=mvc.perform(action(body,"fictional-resolution-http")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.result_revision").value(before+1)).andExpect(jsonPath("$.data.affected.length()").value(1)).andReturn();assertEquals("EXTERNAL_RESULT_CONFIRMED",new JdbcResultState(t.f.source).root(ResultJdbcStoreTest.ROOT).application());assertEquals(0,t.f.count("contents"));assertEquals(slot,new JdbcWorkerState(t.f.source).slot());var replay=mvc.perform(action(body,"fictional-resolution-http")).andExpect(status().isOk()).andReturn();var mapper=JsonMapper.shared();assertEquals(mapper.readTree(first.getResponse().getContentAsString()).get("data"),mapper.readTree(replay.getResponse().getContentAsString()).get("data"));assertEquals(1,t.f.sends);}
    @Test void ActualUnknownAndFailedRemainIndependentAuditActions() throws Exception {mvc.perform(action(command("unknown"),"fictional-resolution-unknown")).andExpect(status().isOk());assertEquals("unknown_external",new JdbcResultState(t.f.source).root(ResultJdbcStoreTest.ROOT).state());mvc.perform(action(command("failed"),"fictional-resolution-failed")).andExpect(status().isOk());assertEquals("failed",new JdbcResultState(t.f.source).root(ResultJdbcStoreTest.ROOT).state());assertNull(new JdbcResultState(t.f.source).root(ResultJdbcStoreTest.ROOT).resultHash());assertEquals(0,t.f.count("contents"));assertEquals(1,t.f.sends);}
    @Test void ClientResultHashFailureAndNativeProofDamageHaveDifferentFixedBoundaries() throws Exception {String body=command("succeeded");String hash=t.command("succeeded").result().resultHash();long before=t.read().root().revision();mvc.perform(action(body.replace(hash,"0".repeat(64)),"fictional-resolution-bad-hash")).andExpect(status().isUnprocessableEntity()).andExpect(jsonPath("$.error.code").value("validation"));assertEquals(before,t.read().root().revision());t.f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='worker_claim'",new byte[32]);String response=mvc.perform(action(body,"fictional-resolution-bad-native")).andExpect(status().isServiceUnavailable()).andExpect(jsonPath("$.error.code").value("temporarily_unavailable")).andReturn().getResponse().getContentAsString();assertFalse(response.contains("SQL"));}
    @Test void PermissionsAndClosedBranchFieldsPrecedeNativeSql() throws Exception {String body=command("succeeded");mvc.perform(action(body.replace("}",",\"expected_content_revision\":null}"),"fictional-resolution-fields")).andExpect(status().isBadRequest());t.f.jdbc.execute("DROP TABLE jobs");mvc.perform(post("/admin/jobs/fictional-root/actions").contentType("application/json").content(body)).andExpect(status().isUnauthorized());when(auth.authenticate("fictional-session")).thenReturn(new IdentityService.Actor("fictional-member","member"));mvc.perform(action(body,"fictional-resolution-role")).andExpect(status().isForbidden());}
}
